Copy the workbook to preserve D:G number formats, then read cached values from Data and parse E/F/G as integers, falling back to D if needed. Write the computed E*365 + F*12 + G values as plain numbers into H2:H78 and unbold the D1:H1 titles. Save the modified workbook to OUT.

```python
import shutil
import re
import openpyxl
from copy import copy
from openpyxl.styles import Font

try:
    shutil.copy(INIT, OUT)
except shutil.SameFileError:
    pass

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = "Data"
if sheet_name not in wb.sheetnames:
    ws = wb.create_sheet(sheet_name)
else:
    ws = wb[sheet_name]

vws = vals[sheet_name] if sheet_name in vals.sheetnames else None

def to_int(value):
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        try:
            return int(round(float(value)))
        except Exception:
            return None
    s = str(value).strip()
    if not s or s.startswith("#"):
        return None
    groups = re.findall(r"-?\d+", s)
    if not groups:
        return None
    try:
        return int(groups[0])
    except Exception:
        return None

def parse_date_text(value):
    if value is None or isinstance(value, bool):
        return None
    if hasattr(value, "year"):
        return (value.year % 100, value.month, value.day)
    if isinstance(value, (int, float)):
        return None
    s = str(value).strip()
    if not s or s.startswith("#"):
        return None
    groups = re.findall(r"\d+", s)
    if len(groups) >= 3:
        try:
            return int(groups[0]), int(groups[1]), int(groups[2])
        except Exception:
            return None
    return None

# Ensure titles exist if the sheet was newly created.
defaults = {
    "D1": "Data",
    "E1": "Year",
    "F1": "Month",
    "G1": "Day",
    "H1": "Sum",
}
for ref, text in defaults.items():
    if ws[ref].value is None:
        ws[ref].value = text

# Do not bold the titles.
for col in "DEFGH":
    cell = ws[f"{col}1"]
    try:
        font = copy(cell.font)
        font.bold = False
        cell.font = font
    except Exception:
        cell.font = Font(bold=False)

last_row = 78
for r in range(2, last_row + 1):
    y = m = d = None

    if vws is not None:
        y = to_int(vws.cell(row=r, column=5).value)
        m = to_int(vws.cell(row=r, column=6).value)
        d = to_int(vws.cell(row=r, column=7).value)

        if y is None or m is None or d is None:
            parsed = parse_date_text(vws.cell(row=r, column=4).value)
            if parsed is not None:
                y, m, d = parsed

    if y is None:
        y = 0
    if m is None:
        m = 0
    if d is None:
        d = 0

    total = y * 365 + m * 12 + d
    ws.cell(row=r, column=8).value = total

print("rows written:", last_row - 1)
print("H2:", ws.cell(row=2, column=8).value)
print("H10:", ws.cell(row=10, column=8).value)
print("H78:", ws.cell(row=78, column=8).value)

wb.save(OUT)
```

